#include "MaterialViewport.h"
#include <algorithm>
#include <cmath>

namespace {
QImage renderMeshPreview(const ModelAsset *asset,const QImage &texture,QSize output,double yaw,double pitch,double distance,double panX,double panY,double scale,double uvScale,double uvX,double uvY,int azimuth,int elevation,int intensity,int ambient,const QVector3D &center,double radius,int targetFaces){QImage out(output,QImage::Format_RGBA8888);out.fill(QColor("#0b1118"));if(!asset||asset->triangles.isEmpty()||texture.isNull())return out;const int side=qMin(output.width(),output.height());const double projection=side*.40/qMax(.0001,radius)/distance*scale,cx=output.width()/2.+panX*side*.3,cy=output.height()/2.+panY*side*.3,pi=pitch*3.141592653589793/180.,ya=yaw*3.141592653589793/180.,lightAz=azimuth*3.141592653589793/180.,lightEl=elevation*3.141592653589793/180.;const QVector3D light(std::cos(lightEl)*std::sin(lightAz),-std::sin(lightEl),std::cos(lightEl)*std::cos(lightAz));struct Face{QPolygonF polygon;QColor color;double depth;};QVector<Face> faces;const int step=qMax(1,asset->triangles.size()/qMax(1,targetFaces));faces.reserve(asset->triangles.size()/step);auto rotate=[&](QVector3D point){point-=center;const float x=point.x()*std::cos(ya)+point.z()*std::sin(ya),z=-point.x()*std::sin(ya)+point.z()*std::cos(ya),y=point.y()*std::cos(pi)-z*std::sin(pi);return QVector3D(x,y,point.y()*std::sin(pi)+z*std::cos(pi));};auto project=[&](const QVector3D &point){return QPointF(cx+point.x()*projection,cy-point.y()*projection);};auto sample=[&](QVector2D uv){double u=uv.x()*uvScale+uvX,v=uv.y()*uvScale+uvY;u-=std::floor(u);v-=std::floor(v);return QColor::fromRgba(texture.pixel(qBound(0,qRound(u*(texture.width()-1)),texture.width()-1),qBound(0,qRound((1-v)*(texture.height()-1)),texture.height()-1)));};for(int i=0;i<asset->triangles.size();i+=step){const auto &triangle=asset->triangles[i];if(triangle.first<0||triangle.second<0||triangle.third<0||triangle.first>=asset->vertices.size()||triangle.second>=asset->vertices.size()||triangle.third>=asset->vertices.size())continue;const auto &a=asset->vertices[triangle.first],&b=asset->vertices[triangle.second],&c=asset->vertices[triangle.third];const QVector3D ra=rotate(a.position),rb=rotate(b.position),rc=rotate(c.position);const QVector3D normal=QVector3D::crossProduct(rb-ra,rc-ra).normalized();if(normal.z()<=-.15)continue;const double shade=qBound(.12,ambient/100.+qMax(0.f,QVector3D::dotProduct(normal,-light))*intensity/100.,1.8);QColor color=sample((a.uv+b.uv+c.uv)/3.);color.setRed(qBound(0,qRound(color.red()*shade),255));color.setGreen(qBound(0,qRound(color.green()*shade),255));color.setBlue(qBound(0,qRound(color.blue()*shade),255));faces.push_back({QPolygonF{project(ra),project(rb),project(rc)},color,(ra.z()+rb.z()+rc.z())/3.});}std::sort(faces.begin(),faces.end(),[](const Face &left,const Face &right){return left.depth<right.depth;});QPainter painter(&out);painter.setRenderHint(QPainter::Antialiasing);for(const auto &face:faces){painter.setPen(QPen(QColor(0,0,0,35),.35));painter.setBrush(face.color);painter.drawPolygon(face.polygon);}painter.setPen(QColor("#aebac7"));painter.setFont(QFont("Segoe UI",8));painter.drawText(QRect(10,output.height()-28,output.width()-20,20),Qt::AlignLeft|Qt::AlignVCenter,QString("MESH · %1 triangles · UV material preview").arg(asset->triangles.size()));return out;}
}

MaterialViewport::MaterialViewport(QWidget *parent):QWidget(parent){setMinimumSize(520,520);setMouseTracking(true);setFocusPolicy(Qt::StrongFocus);setAttribute(Qt::WA_OpaquePaintEvent);highQualityTimer.setSingleShot(true);highQualityTimer.setInterval(90);connect(&highQualityTimer,&QTimer::timeout,this,[this]{interactionActive=false;update();});}
void MaterialViewport::setMaterial(const QImage &image){material=image;update();}
void MaterialViewport::setMesh(const ModelAsset *asset){if(meshAsset==asset&&meshSourcePath==(asset?asset->sourcePath:QString{}))return;meshAsset=asset;meshSourcePath=asset?asset->sourcePath:QString{};meshCenter={};meshRadius=1.;if(!meshAsset||meshAsset->vertices.isEmpty()){update();return;}QVector3D minimum=meshAsset->vertices.first().position,maximum=minimum;for(const auto &vertex:meshAsset->vertices){minimum.setX(qMin(minimum.x(),vertex.position.x()));minimum.setY(qMin(minimum.y(),vertex.position.y()));minimum.setZ(qMin(minimum.z(),vertex.position.z()));maximum.setX(qMax(maximum.x(),vertex.position.x()));maximum.setY(qMax(maximum.y(),vertex.position.y()));maximum.setZ(qMax(maximum.z(),vertex.position.z()));}meshCenter=(minimum+maximum)*.5;meshRadius=qMax(.0001,double((maximum-minimum).length()*.5));update();}
void MaterialViewport::setLighting(int azimuth,int elevation,int intensity,int ambientValue){lightAzimuth=azimuth;lightElevation=elevation;lightIntensity=intensity;ambient=ambientValue;update();}
void MaterialViewport::setModelTransform(double scale,double textureScale,double textureX,double textureY){modelScale=qBound(.1,scale,4.);uvScale=qBound(.01,textureScale,4.);uvX=textureX;uvY=textureY;update();}
void MaterialViewport::scheduleHighQuality(){interactionActive=true;highQualityTimer.start();}
void MaterialViewport::mousePressEvent(QMouseEvent *event){last=event->pos();if(event->button()==Qt::MiddleButton){scheduleHighQuality();event->accept();}}
void MaterialViewport::orbitBy(QPoint delta,bool pan){if(delta.isNull())return;if(pan){panX+=delta.x()/180.;panY+=delta.y()/180.;}else{yaw+=delta.x()*.55;pitch=qBound(-80.,pitch+delta.y()*.55,80.);}scheduleHighQuality();update();}
void MaterialViewport::zoomBy(int wheelDelta){if(!wheelDelta)return;distance=qBound(1.15,distance-wheelDelta/1200.,6.);scheduleHighQuality();update();}
void MaterialViewport::mouseMoveEvent(QMouseEvent *event){if(!(event->buttons()&Qt::MiddleButton))return;const QPoint delta=event->pos()-last;last=event->pos();orbitBy(delta,event->modifiers()&Qt::ShiftModifier);event->accept();}
void MaterialViewport::mouseReleaseEvent(QMouseEvent *event){if(event->button()==Qt::MiddleButton){highQualityTimer.start();event->accept();}}
void MaterialViewport::wheelEvent(QWheelEvent *event){if(event->modifiers()&Qt::ControlModifier)zoomBy(event->angleDelta().y());event->accept();}
QImage MaterialViewport::renderPreview(QSize output) const{if(!output.isValid())output={512,512};if(meshAsset&&!meshAsset->triangles.isEmpty())return renderMeshPreview(meshAsset,material,output,yaw,pitch,distance,panX,panY,modelScale,uvScale,uvX,uvY,lightAzimuth,lightElevation,lightIntensity,ambient,meshCenter,meshRadius,interactionActive?4500:18000);QImage out(output,QImage::Format_RGBA8888);out.fill(QColor("#0b1118"));if(material.isNull())return out;const int side=qMin(output.width(),output.height());const double radius=side*.37/distance*2.5*modelScale,cx=output.width()/2.+panX*radius,cy=output.height()/2.+panY*radius,az=lightAzimuth*3.141592653589793/180.,el=lightElevation*3.141592653589793/180.,lx=std::cos(el)*std::sin(az),ly=-std::sin(el),lz=std::cos(el)*std::cos(az),ya=yaw*3.141592653589793/180.,pi=pitch*3.141592653589793/180.;for(int y=qMax(0,int(cy-radius));y<qMin(output.height(),int(cy+radius));++y)for(int x=qMax(0,int(cx-radius));x<qMin(output.width(),int(cx+radius));++x){const double nx=(x-cx)/radius,ny=(y-cy)/radius,d=nx*nx+ny*ny;if(d>1)continue;const double nz=std::sqrt(1-d),rx=nx*std::cos(ya)+nz*std::sin(ya),rz=-nx*std::sin(ya)+nz*std::cos(ya),ry=ny*std::cos(pi)-rz*std::sin(pi),rz2=ny*std::sin(pi)+rz*std::cos(pi);double u=.5+std::atan2(rx,rz2)/(2*3.141592653589793),v=.5-std::asin(qBound(-1.,ry,1.))/3.141592653589793;u=u*uvScale+uvX;v=v*uvScale+uvY;u-=std::floor(u);v-=std::floor(v);const QRgb pixel=material.pixel(qBound(0,qRound(u*(material.width()-1)),material.width()-1),qBound(0,qRound(v*(material.height()-1)),material.height()-1));const double light=qBound(0.,ambient/100.+qMax(0.,nx*lx+ny*ly+nz*lz)*lightIntensity/100.,2.);out.setPixel(x,y,qRgba(qBound(0,qRound(qRed(pixel)*light),255),qBound(0,qRound(qGreen(pixel)*light),255),qBound(0,qRound(qBlue(pixel)*light),255),255));}QPainter overlay(&out);overlay.setRenderHint(QPainter::Antialiasing);overlay.setPen(QColor("#57dd7b"));overlay.setFont(QFont("Segoe UI",8,QFont::Bold));overlay.drawText(QPointF(cx-10,cy-radius-12),"TOP");overlay.setPen(QColor("#ed6675"));overlay.drawText(QPointF(cx-18,cy+radius+18),"BOTTOM");const QPointF origin(output.width()-44,output.height()-44);overlay.setBrush(QColor(8,11,13,185));overlay.setPen(Qt::NoPen);overlay.drawEllipse(origin,25,25);auto axis=[&](double x,double y,QColor color,QString name){overlay.setPen(QPen(color,2.5));const QPointF end=origin+QPointF(x*22,y*22);overlay.drawLine(origin,end);overlay.setBrush(color);overlay.drawEllipse(end,3,3);overlay.drawText(end+QPointF(4,-3),name);};axis(1,0,QColor("#ff5c62"),"X");axis(0,-1,QColor("#57dd7b"),"Y");axis(-.6,.7,QColor("#3ddcff"),"Z");return out;}
void MaterialViewport::paintEvent(QPaintEvent *){QPainter painter(this);painter.setRenderHint(QPainter::SmoothPixmapTransform);const QSize liveSize=interactionActive?QSize(qMax(1,width()/2),qMax(1,height()/2)):size();painter.drawImage(rect(),renderPreview(liveSize));painter.setPen(QColor("#aebac7"));painter.drawText(12,height()-12,"Middle drag: orbit  ·  Shift + middle: pan  ·  Ctrl + wheel: zoom");}
